INSERT INTO recipes VALUES ('chicken-ginger','鶏肉の生姜焼き＋ご飯',1,20,'["フライパン"]','["炊飯済みのご飯を用意する（冷凍ご飯は温める）。野菜を洗い、薄切り・小房にする。", "主材料を一口大にする。豆腐は軽く水切りする。卵は溶いておく。", "生姜・しょうゆ・砂糖を混ぜ、主材料と野菜に絡めて焼く。", "肉・魚・卵は中心まで十分加熱する。豆腐と卵の料理は最後に溶き卵を加えて固まるまで加熱する。", "ご飯と一緒に盛り付ける。"]','["夕食", "概算", "炊飯済みご飯"]',0);
