INSERT INTO recipes VALUES ('salmon-tomato','鮭のトマト煮＋ご飯',1,25,'["鍋"]','["炊飯済みのご飯を用意する（冷凍ご飯は温める）。野菜を洗い、薄切り・小房にする。", "主材料を一口大にする。豆腐は軽く水切りする。卵は溶いておく。", "刻んだトマト・たまねぎと主材料を少量の水で煮て、しょうゆで調える。", "肉・魚・卵は中心まで十分加熱する。豆腐と卵の料理は最後に溶き卵を加えて固まるまで加熱する。", "ご飯と一緒に盛り付ける。"]','["夕食", "概算", "炊飯済みご飯"]',0);
